const value = decode(event.schemaVersion, event.payload); // unknown versions go to quarantine
const start = Math.floor(event.time / width) * width;
if (start + width <= watermark) return quarantine(event, "late"); // its window already closed
const win = open.get(start) ?? openWindow(start);
if (win.ids.has(event.id)) return "duplicate";
win.ids.add(event.id); win.sum += value; win.count++;
maxEventTime = Math.max(maxEventTime, event.time); watermark = Math.max(watermark, maxEventTime - lateness);
for (const [s, w] of open) if (s + width <= watermark) { emitFinal(s, w.sum, w.count); open.delete(s); } // evicts sums and IDs

const cp = loadCommittedCheckpoint();
restoreWindowState(cp.openWindows, cp.watermark); // each open window carries its event-ID set
for (const event of source.after(cp.offsets)) applyIfNewEventId(event);
commitOutputVersionsWithCheckpoint();
// Closed windows were emitted and evicted before the checkpoint; their late events stay in quarantine.

if (windowStore.hasReceipt(batch.id)) return "already-committed";
const deltas = new Map(), ids = [];
for (const e of normalizedSortedUnique(batch)) { // repeats inside the batch collapse here
 const start = Math.floor(e.time / width) * width;
 if (start + width <= batch.watermark) { quarantine(e, batch.id); continue; }
 if (windowStore.idIndex(e.key, start).has(e.id)) continue; // already counted by an earlier batch
 addDelta(deltas, e.key, start, e.value); ids.push([e.key, start, e.id]);
}
transaction(() => { mergeDeltas(deltas); insertIds(ids); dropIdIndexForWindowsEndingBy(batch.watermark); insertBatchReceiptUnique(batch.id); });

const batch = loadFrozenBatch(batchId);
if (windowStore.hasBatchReceipt(batch.id)) return advanceOffsets(batch.upperOffsets);
const {deltas, ids} = recomputeFromImmutableEvents(batch, batch.watermark, windowStore.idIndex);
transaction(()=> { mergeDeltas(deltas); insertIds(ids); insertBatchReceiptUnique(batch.id); });
advanceOffsets(batch.upperOffsets);
